from pathlib import Path


def replace_once(text: str, old: str, new: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"expected one occurrence, got {count}: {old[:120]!r}")
    return text.replace(old, new, 1)


# ---------------------------------------------------------------------------
# Rust cache: add a dense, no-COLD, budget-safe transactional write.
# ---------------------------------------------------------------------------
p = Path("slhav2-vram/src/elastic_cache.rs")
s = p.read_text()
marker = '''    /// Remove one stable slot and all resident/backing bytes it owns.\n'''
insert = '''    /// Transactionally write one dense-attention slot without ever charging\n    /// more than `target_resident_bytes` to resident KV storage.\n    ///\n    /// The target is clamped to the cache hard budget. Existing HOT slots may\n    /// be demoted to WARM to make room, but this operation never creates COLD\n    /// state because every active dense-attention key must remain scoreable.\n    /// The new value is stored directly as HOT when it fits or directly as\n    /// WARM (96 resident bytes + reversible residual backing) otherwise.\n    /// Any impossible target rolls the complete mutation back.\n    pub fn write_at_dense_budget(\n        &mut self,\n        slot: usize,\n        mut tile: [u8; codec::TILE_BYTES],\n        target_resident_bytes: usize,\n    ) -> Result<PhysicalTier, &'static str> {\n        let snapshot_slots = self.slots.clone();\n        let snapshot_resident = self.resident_bytes;\n        let snapshot_next_seq = self.next_seq;\n        let target = target_resident_bytes.min(self.config_budget_bytes());\n\n        let result = (|| {\n            if self.resident_bytes > self.config_budget_bytes() {\n                return Err("physical residency already exceeds hard budget");\n            }\n\n            let required_len = slot.checked_add(1).ok_or("slot index overflow")?;\n            if self.slots.len() < required_len {\n                self.slots\n                    .try_reserve(required_len - self.slots.len())\n                    .map_err(|_| "slot allocation failed")?;\n                self.slots.resize_with(required_len, || None);\n            }\n\n            let pinned = self.slots[slot]\n                .as_ref()\n                .is_some_and(|state| state.tier == PhysicalTier::Pinned);\n            let old_resident = self.slots[slot]\n                .as_ref()\n                .map_or(0, PhysicalSlot::allocated_bytes);\n            self.slots[slot] = None;\n            self.resident_bytes = self\n                .resident_bytes\n                .checked_sub(old_resident)\n                .ok_or("resident byte accounting underflow")?;\n\n            let minimum_new_resident = if pinned {\n                codec::TILE_BYTES\n            } else {\n                WARM_PACKED_BYTES\n            };\n\n            while self\n                .resident_bytes\n                .checked_add(minimum_new_resident)\n                .ok_or("resident byte accounting overflow")?\n                > target\n            {\n                let prior = self.resident_bytes;\n                if self.demote_lowest_importance(1) == 0 || self.resident_bytes == prior {\n                    return Err("dense write target cannot be satisfied without COLD residency");\n                }\n            }\n\n            Self::set_warm_flag(&mut tile, false);\n            let hot_fits = self\n                .resident_bytes\n                .checked_add(codec::TILE_BYTES)\n                .is_some_and(|bytes| bytes <= target);\n            let tier = if pinned {\n                PhysicalTier::Pinned\n            } else if hot_fits {\n                PhysicalTier::Hot\n            } else {\n                PhysicalTier::Warm\n            };\n\n            let (bytes, warm_residual) = match tier {\n                PhysicalTier::Hot | PhysicalTier::Pinned => (tile.to_vec(), None),\n                PhysicalTier::Warm => {\n                    let mut residual = [0u8; RESIDUAL_BYTES];\n                    residual.copy_from_slice(\n                        &tile[codec::RESIDUAL_OFFSET\n                            ..codec::RESIDUAL_OFFSET + RESIDUAL_BYTES],\n                    );\n                    Self::set_warm_flag(&mut tile, true);\n                    (codec::pack_warm(&tile).to_vec(), Some(residual))\n                }\n                PhysicalTier::Cold => unreachable!("dense write never creates COLD state"),\n            };\n\n            let next_resident = self\n                .resident_bytes\n                .checked_add(bytes.len())\n                .ok_or("resident byte accounting overflow")?;\n            if next_resident > target || next_resident > self.config_budget_bytes() {\n                return Err("dense write would exceed resident hard budget");\n            }\n\n            self.slots[slot] = Some(PhysicalSlot {\n                bytes,\n                offloaded: None,\n                warm_residual,\n                tier,\n                seq: self.next_seq,\n                importance: 0.0,\n            });\n            self.next_seq = self.next_seq.saturating_add(1);\n            self.resident_bytes = next_resident;\n            self.verify_accounting()?;\n            Ok(tier)\n        })();\n\n        if result.is_err() {\n            self.slots = snapshot_slots;\n            self.resident_bytes = snapshot_resident;\n            self.next_seq = snapshot_next_seq;\n            debug_assert!(self.verify_accounting().is_ok());\n        }\n        result\n    }\n\n'''
if marker not in s:
    raise RuntimeError("missing clear_slot marker")
s = s.replace(marker, insert + marker, 1)

marker = '''    #[test]\n    fn fixed_slot_rewrite_is_bounded_and_drops_old_backing() {\n'''
insert = '''    #[test]\n    fn dense_budget_write_admits_warm_directly_and_rolls_back_impossible_target() {\n        let mut cache = ElasticKvCache::new(192, "dense-budget");\n\n        let tier = cache\n            .write_at_dense_budget(0, make_tile(1), WARM_PACKED_BYTES)\n            .unwrap();\n        assert_eq!(tier, PhysicalTier::Warm);\n        assert_eq!(cache.resident_bytes(), WARM_PACKED_BYTES);\n        assert_eq!(cache.offloaded_bytes(), RESIDUAL_BYTES);\n        assert_eq!(cache.counts(), (0, 1, 0, 0));\n\n        let before_counts = cache.counts();\n        let before_resident = cache.resident_bytes();\n        let before_offloaded = cache.offloaded_bytes();\n        assert!(cache\n            .write_at_dense_budget(1, make_tile(2), WARM_PACKED_BYTES)\n            .is_err());\n        assert_eq!(cache.counts(), before_counts);\n        assert_eq!(cache.resident_bytes(), before_resident);\n        assert_eq!(cache.offloaded_bytes(), before_offloaded);\n        assert_eq!(cache.tier(1), None);\n    }\n\n    #[test]\n    fn dense_budget_write_demotes_existing_hot_without_cold() {\n        let mut cache = ElasticKvCache::new(192, "dense-budget");\n        assert_eq!(\n            cache.write_at_dense_budget(0, make_tile(1), 192).unwrap(),\n            PhysicalTier::Hot\n        );\n        assert_eq!(cache.resident_bytes(), 128);\n\n        assert_eq!(\n            cache.write_at_dense_budget(1, make_tile(2), 192).unwrap(),\n            PhysicalTier::Warm\n        );\n        assert_eq!(cache.resident_bytes(), 192);\n        assert_eq!(cache.offloaded_bytes(), 64);\n        assert_eq!(cache.counts(), (0, 2, 0, 0));\n        cache.verify_accounting().unwrap();\n    }\n\n'''
if marker not in s:
    raise RuntimeError("missing elastic cache test marker")
s = s.replace(marker, insert + marker, 1)
p.write_text(s)


# ---------------------------------------------------------------------------
# C ABI: expose exactly one budget-safe dense write operation.
# ---------------------------------------------------------------------------
p = Path("slha-c/src/elastic_ffi.rs")
s = p.read_text()
marker = '''/// Clear one stable slot and all backing owned by it.\n'''
insert = '''/// Transactionally write a dense-attention tile under an exact resident target.\n///\n/// Existing HOT slots may become WARM, but the operation never creates COLD\n/// slots and never commits resident accounting above `target_resident_bytes`.\n///\n/// # Safety\n/// `tile` must point to one readable `SciRustSlhaTile`. Unaligned storage is\n/// accepted. `handle` may be any pointer value; only registered handles are\n/// accepted and the handle itself is never dereferenced.\n#[no_mangle]\npub unsafe extern "C" fn slha_elastic_cache_write_dense_budget(\n    handle: *mut SlhaElasticKvCache,\n    slot: usize,\n    tile: *const SciRustSlhaTile,\n    target_resident_bytes: usize,\n) -> i32 {\n    ffi_status(|| {\n        let cache = cache_arc(handle)?;\n        // SAFETY: guaranteed by this function's caller contract.\n        let bytes = unsafe { read_tile_unaligned(tile) }?;\n        lock_cache(&cache)\n            .write_at_dense_budget(slot, bytes, target_resident_bytes)\n            .map(|_| ())\n            .map_err(|error| cache_error("elastic dense-budget write failed", error))\n    })\n}\n\n'''
if marker not in s:
    raise RuntimeError("missing clear-slot FFI marker")
s = s.replace(marker, insert + marker, 1)

marker = '''    #[test]\n    fn strided_scoring_addresses_one_interleaved_layer_transactionally() {\n'''
insert = '''    #[test]\n    fn ffi_dense_budget_write_creates_warm_without_cold_and_rolls_back() {\n        let handle = slha_elastic_cache_new(192);\n        assert!(!handle.is_null());\n        let input = tile();\n\n        assert_eq!(\n            // SAFETY: test passes one live local tile and a registered handle.\n            unsafe { slha_elastic_cache_write_dense_budget(handle, 0, &input, 96) },\n            SLHA_OK\n        );\n        let mut snapshot = SlhaElasticKvCacheStats::default();\n        assert_eq!(stats(handle, &mut snapshot), SLHA_OK);\n        assert_eq!(snapshot.resident_bytes, 96);\n        assert_eq!(snapshot.offloaded_bytes, 32);\n        assert_eq!(snapshot.hot_slots, 0);\n        assert_eq!(snapshot.warm_slots, 1);\n        assert_eq!(snapshot.cold_slots, 0);\n\n        assert_eq!(\n            // SAFETY: the same tile remains readable for the second call.\n            unsafe { slha_elastic_cache_write_dense_budget(handle, 1, &input, 96) },\n            SLHA_ERR_DIMENSION\n        );\n        let mut after = SlhaElasticKvCacheStats::default();\n        assert_eq!(stats(handle, &mut after), SLHA_OK);\n        assert_eq!(after, snapshot);\n        assert_eq!(slha_elastic_cache_tier(handle, 1), SLHA_ELASTIC_TIER_ABSENT);\n        assert_eq!(slha_elastic_cache_free(handle), SLHA_OK);\n    }\n\n'''
if marker not in s:
    raise RuntimeError("missing strided FFI test marker")
s = s.replace(marker, insert + marker, 1)
p.write_text(s)

p = Path("slha-c/include/slha.h")
s = p.read_text()
old = '''int32_t slha_elastic_cache_write(SlhaElasticKvCache* cache, size_t slot, const SciRustSlhaTile* tile);\n'''
new = old + '''int32_t slha_elastic_cache_write_dense_budget(\n    SlhaElasticKvCache* cache,\n    size_t slot,\n    const SciRustSlhaTile* tile,\n    size_t target_resident_bytes\n);\n'''
s = replace_once(s, old, new)
p.write_text(s)


# ---------------------------------------------------------------------------
# llama.cpp bridge: make admission atomic; no write-then-demote overshoot.
# ---------------------------------------------------------------------------
p = Path("integration/llama.cpp/shim/slha_external_k.cpp")
s = p.read_text()
old = '''    const int32_t write_rc = slha_elastic_cache_write(g_ccos_cache, slot, tile);\n    if (write_rc != SLHA_OK) {\n        g_cache_misses.fetch_add(1, std::memory_order_relaxed);\n        return false;\n    }\n\n    SlhaElasticKvCacheStats after_write{};\n    if (!snapshot_ccos(&after_write)) {\n        g_cache_misses.fetch_add(1, std::memory_order_relaxed);\n        return false;\n    }\n    record_cache_snapshot(after_write);\n\n    if (after_write.resident_bytes > g_ccos_budget_bytes) {\n        g_budget_enforcements.fetch_add(1, std::memory_order_relaxed);\n        const auto budget_start = steady_clock::now();\n        const int32_t budget_rc =\n            slha_elastic_cache_demote_to(g_ccos_cache, g_ccos_budget_bytes);\n        const auto budget_end = steady_clock::now();\n        g_budget_ns.fetch_add(\n            static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(\n                budget_end - budget_start).count()),\n            std::memory_order_relaxed);\n        if (budget_rc != SLHA_OK) {\n            g_budget_failures.fetch_add(1, std::memory_order_relaxed);\n            return false;\n        }\n    }\n\n    SlhaElasticKvCacheStats final_stats{};\n'''
new = '''    const int32_t prior_tier = slha_elastic_cache_tier(g_ccos_cache, slot);\n    size_t prior_slot_resident = 0;\n    if (prior_tier == SLHA_ELASTIC_TIER_HOT || prior_tier == SLHA_ELASTIC_TIER_PINNED) {\n        prior_slot_resident = slha_elastic_hot_resident_bytes();\n    } else if (prior_tier == SLHA_ELASTIC_TIER_WARM) {\n        prior_slot_resident = slha_elastic_warm_resident_bytes();\n    }\n    if (before.resident_bytes < prior_slot_resident) {\n        g_budget_failures.fetch_add(1, std::memory_order_relaxed);\n        return false;\n    }\n    size_t hot_after_rewrite = 0;\n    const size_t resident_without_slot = before.resident_bytes - prior_slot_resident;\n    if (!checked_add(\n            resident_without_slot, slha_elastic_hot_resident_bytes(), &hot_after_rewrite)) {\n        g_budget_failures.fetch_add(1, std::memory_order_relaxed);\n        return false;\n    }\n    const bool budget_action = hot_after_rewrite > g_ccos_budget_bytes;\n    if (budget_action) {\n        g_budget_enforcements.fetch_add(1, std::memory_order_relaxed);\n    }\n\n    const auto budget_start = steady_clock::now();\n    const int32_t write_rc = slha_elastic_cache_write_dense_budget(\n        g_ccos_cache, slot, tile, g_ccos_budget_bytes);\n    const auto budget_end = steady_clock::now();\n    if (budget_action) {\n        // This is wall time for the complete budget-aware admission call. It\n        // includes the direct HOT/WARM write because admission and mutation are\n        // intentionally one atomic operation; it is not presented as a pure\n        // codec-only timing.\n        g_budget_ns.fetch_add(\n            static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::nanoseconds>(\n                budget_end - budget_start).count()),\n            std::memory_order_relaxed);\n    }\n    if (write_rc != SLHA_OK) {\n        g_budget_failures.fetch_add(1, std::memory_order_relaxed);\n        g_cache_misses.fetch_add(1, std::memory_order_relaxed);\n        return false;\n    }\n\n    SlhaElasticKvCacheStats final_stats{};\n'''
s = replace_once(s, old, new)
p.write_text(s)


# ---------------------------------------------------------------------------
# C++ contract: make the transient-overshoot bug observable through peaks.
# ---------------------------------------------------------------------------
p = Path("integration/llama.cpp/tests/external_k_contract_tests.cpp")
s = p.read_text()
old = '''    assert(stats.resident_bytes == 96u);\n    assert(stats.offloaded_bytes == 32u);\n    assert(stats.budget_enforcements == 1u);\n'''
new = '''    assert(stats.resident_bytes == 96u);\n    assert(stats.offloaded_bytes == 32u);\n    assert(stats.peak_resident_bytes == 96u);\n    assert(stats.peak_offloaded_bytes == 32u);\n    assert(stats.budget_enforcements == 1u);\n'''
s = replace_once(s, old, new)
p.write_text(s)
